class Gradebook:
    def __init__(self) -> None:
        # Store assignments: {name: {"weight": float, "kind": str}}
        self.assignments = {}
        # Store grades: {student: {assignment: grade}}
        self.grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in ["homework", "quiz"]:
            raise ValueError("kind must be 'homework' or 'quiz'")
        self.assignments[name] = {"weight": weight, "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        # Validate grade is within Polish scale
        if grade < 2.0 or grade > 5.0:
            raise ValueError("Grade must be between 2.0 and 5.0")

        # Initialize student's grade dict if it doesn't exist
        if student not in self.grades:
            self.grades[student] = {}

        # Record the grade
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        # If student has no grades, return 0.0
        if student not in self.grades or not self.grades[student]:
            return 0.0

        # Get all assignments for this student that have been recorded
        student_grades = self.grades[student]

        # Separate homework and quiz grades
        homework_grades = {}
        quiz_grades = {}

        for assignment, grade in student_grades.items():
            if assignment in self.assignments:
                kind = self.assignments[assignment]["kind"]
                if kind == "homework":
                    homework_grades[assignment] = grade
                elif kind == "quiz":
                    quiz_grades[assignment] = grade

        # Process quiz grades: drop the lowest if there's more than one
        final_quiz_grades = {}
        if len(quiz_grades) > 1:
            # Find the lowest quiz grade
            lowest_quiz_grade = min(quiz_grades.values())
            # Keep all quiz grades except one instance of the lowest
            dropped = False
            for assignment, grade in quiz_grades.items():
                if grade == lowest_quiz_grade and not dropped:
                    dropped = True
                    continue
                final_quiz_grades[assignment] = grade
        else:
            final_quiz_grades = quiz_grades

        # Combine homework and final quiz grades
        all_grades = {**homework_grades, **final_quiz_grades}

        # Calculate weighted average
        total_weighted_sum = 0.0
        total_weight = 0.0

        for assignment, grade in all_grades.items():
            if assignment in self.assignments:
                weight = self.assignments[assignment]["weight"]
                total_weighted_sum += grade * weight
                total_weight += weight

        # Handle case where total_weight is 0 (no valid assignments)
        if total_weight == 0.0:
            return 0.0

        average_value = total_weighted_sum / total_weight
        return round(average_value, 2)
